// Workflow JS action: select_unrecorded_tests
// Input : records from execute_dql-find_finished_tests (tests whose last span is older than the quiet period)
// Output: { tests: [...] } = finished tests that do NOT yet have a loadtest.summary bizevent.
// The summary bizevent is written LAST for each test, so "no summary" == "not (fully) processed yet".
import { execution } from '@dynatrace-sdk/automation-utils';
import { queryExecutionClient } from '@dynatrace-sdk/client-query';

const PREVIOUS_STEP = 'execute_dql-find_finished_tests';
const PAD_MS = 5 * 60 * 1000;   // widen each test's query window by 5 min on both sides
const MAX_TESTS = 50;           // bound the run; remaining tests are picked up on the next run

// DQL returns nanosecond precision; trim to milliseconds so Date can parse it everywhere.
const toMs = (s) => new Date(String(s).replace(/(\.\d{3})\d+Z$/, '$1Z')).getTime();

async function existingSummaries(teUuids) {
  const list = teUuids.map((id) => `"${id}"`).join(', ');
  const result = await queryExecutionClient.queryExecute({
    body: {
      query: `fetch bizevents, from: -365d
        | filter event.type == "loadtest.summary"
        | filter in(te_uuid, {${list}})
        | fields te_uuid
        | dedup te_uuid`,
      requestTimeoutMilliseconds: 30000,
      maxResultRecords: 100000,
    },
  });
  return new Set((result.result?.records ?? []).map((r) => r.te_uuid));
}

export default async function ({ executionId }) {
  const ex = await execution(executionId);
  const records = (await ex.result(PREVIOUS_STEP))?.records ?? [];
  console.log(`${records.length} finished test execution(s) found in the lookback window`);
  if (records.length === 0) return { tests: [] };

  const candidates = records.map((r) => ({ ...r, te_uuid: String(r.test_execution).slice(-36) }));
  // If the existence check fails we must NOT proceed (would re-ingest everything) - let the step fail and retry next run.
  const done = await existingSummaries([...new Set(candidates.map((c) => c.te_uuid))]);

  const pending = candidates
    .filter((c) => !done.has(c.te_uuid))
    .sort((a, b) => toMs(a.test_start) - toMs(b.test_start));
  console.log(`${pending.length} not yet recorded (${done.size} already have a summary)`);
  if (pending.length > MAX_TESTS) console.log(`Processing the oldest ${MAX_TESTS}; ${pending.length - MAX_TESTS} deferred to next run`);

  const tests = pending.slice(0, MAX_TESTS).map((c) => ({
    test_execution: c.test_execution,
    te_uuid: c.te_uuid,
    source_id: c.source_id,
    test_start: c.test_start,
    test_end: c.test_end,
    window_start: new Date(toMs(c.test_start) - PAD_MS).toISOString(),
    window_end: new Date(toMs(c.test_end) + PAD_MS).toISOString(),
  }));
  tests.forEach((t) => console.log(`${t.test_execution}  ${t.test_start} -> ${t.test_end}`));
  return { tests };
}

// Workflow JS action: write-bizevents_step_execution_details_performance
// Replaces the lookup-table approach for testsummary_responsetime_detailed.
// Reads DQL step results (possibly looped), deduplicates against existing
// bizevents, and ingests new records as business events.

import { execution } from '@dynatrace-sdk/automation-utils';
import { queryExecutionClient } from '@dynatrace-sdk/client-query';

const PREVIOUS_STEP = 'execute_dql-step_execution_performance';
const EVENT_TYPE    = 'loadtest.responsetime.detailed';
const EVENT_SOURCE  = 'loadtest-workflow';
const BATCH_SIZE    = 500; // stay well within 5 MB payload limit

// ── Dedup check ───────────────────────────────────────────────────────────────

async function getExistingRowKeys(teUuids) {
  const uuidList = teUuids.map(id => `"${id}"`).join(', ');
  try {
    const result = await queryExecutionClient.queryExecute({
      body: {
        query: `fetch bizevents, from: -365d
          | filter in(event.type, {"neoload.responsetime.detailed", "loadtest.responsetime.detailed"})
          | filter in(te_uuid, {${uuidList}})
          | fields row_key
          | dedup row_key`,
        requestTimeoutMilliseconds: 30000,
        maxResultRecords: 100000,
      },
    });
    return new Set((result.result?.records ?? []).map(r => r.row_key));
  } catch (e) {
    console.warn('Could not check existing bizevents (will attempt full ingest):', e.message);
    return new Set();
  }
}

// ── Ingest ────────────────────────────────────────────────────────────────────

async function ingestBatch(events) {
  const response = await fetch(
    '/platform/classic/environment-api/v2/bizevents/ingest',
    {
      method: 'POST',
      headers: { 'Content-Type': 'application/cloudevents-batch+json' },
      body: JSON.stringify(events),
    }
  );
  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Ingest failed [${response.status}]: ${errorText}`);
  }
}

// ── Main ──────────────────────────────────────────────────────────────────────

export default async function ({ executionId }) {
  const ex = await execution(executionId);
  const stepResult = await ex.result(PREVIOUS_STEP);

  // When the DQL step runs inside a loop, ex.result() returns an array
  const resultArray = Array.isArray(stepResult) ? stepResult : [stepResult];
  const records = resultArray.flatMap((r) => r?.records ?? []);

  console.log(`Received ${records.length} records across ${resultArray.length} iteration(s)`);

  if (records.length === 0) {
    console.log('No records returned — nothing to ingest');
    return { processed: 0 };
  }

  const allRecords = records.map((r) => ({
    ...r,
    row_key: `${r.te_uuid}::${r.source_id}::${r.zone}::${r.transaction_name}::${r.script_name}::${r.page_context ?? ''}`,
  }));

  const teUuids = [...new Set(allRecords.map(r => r.te_uuid))];
  console.log(`Found ${teUuids.length} unique test execution(s): ${teUuids.join(', ')}`);

  const existingKeys = await getExistingRowKeys(teUuids);
  console.log(`${existingKeys.size} existing event(s) found — skipping duplicates`);

  const newRecords = allRecords.filter(r => !existingKeys.has(r.row_key));
  console.log(`New records to ingest: ${newRecords.length}`);

  if (newRecords.length === 0) {
    console.log('All records already ingested — nothing to do');
    return { processed: 0, skipped: allRecords.length };
  }

  // Build CloudEvents batch — record fields spread as top-level extensions
  const events = newRecords.map((r) => ({
    specversion: '1.0',
    id: r.row_key,
    source: EVENT_SOURCE,
    type: EVENT_TYPE,
    time: r.test_start ?? new Date().toISOString(),
    ...r,
  }));

  let ingested = 0;
  for (let i = 0; i < events.length; i += BATCH_SIZE) {
    const batch = events.slice(i, i + BATCH_SIZE);
    await ingestBatch(batch);
    ingested += batch.length;
    console.log(`Batch ${Math.floor(i / BATCH_SIZE) + 1}: ingested ${batch.length} events (${ingested}/${events.length} total)`);
  }

  return { processed: ingested, skipped: allRecords.length - newRecords.length };
}

